DECLARE @Reader TABLE (ReaderId int, NickName nvarchar(20));
INSERT INTO @Reader VALUES (1, NULL);
SELECT ISNULL(NickName, N'(未設定)') FROM @Reader   -- '(未設定)'

DECLARE @Copy TABLE (CopyNo int, LoanCount int);
INSERT INTO @Copy VALUES (1, 0);
SELECT CopyNo, 100.0 / NULLIF(LoanCount, 0) AS AvgLoad FROM @Copy   -- NULL，不拋出除以零

DECLARE @Copy TABLE (CopyNo int, Status tinyint);
INSERT INTO @Copy VALUES (1, 1), (2, 0);
SELECT CopyNo, IIF(Status = 1, N'借出', N'在架') FROM @Copy ORDER BY CopyNo   -- 1: 借出；2: 在架

DECLARE @Copy TABLE (CopyNo varchar(10));
INSERT INTO @Copy VALUES ('A01'), (NULL), ('A02');
SELECT STRING_AGG(CopyNo, ', ') WITHIN GROUP (ORDER BY CopyNo) FROM @Copy   -- 'A01, A02'（NULL 直接略過，不留分隔字元）

DECLARE @Copy TABLE (BranchId int, CopyNo varchar(10));
INSERT INTO @Copy VALUES (1, 'A01'), (1, 'A02'), (2, 'B01');
SELECT BranchId, STRING_AGG(CopyNo, ', ') WITHIN GROUP (ORDER BY CopyNo)
FROM @Copy GROUP BY BranchId ORDER BY BranchId   -- 1: 'A01, A02'；2: 'B01'

DECLARE @Copy TABLE (CopyNo varchar(10));
INSERT INTO @Copy VALUES ('A01'), ('A02'), ('A03');
SELECT STUFF((
  SELECT ', ' + CopyNo FROM @Copy ORDER BY CopyNo FOR XML PATH('')
), 1, 2, '')   -- 'A01, A02, A03'；SQL Server 2017 起改用 STRING_AGG 更直覺

DECLARE @Loan TABLE (LoanId int, LoanDate datetime2, ReturnDate datetime2);
INSERT INTO @Loan VALUES (1, '2026-09-01 09:00:00', '2026-09-08 09:00:00');
SELECT DATEDIFF_BIG(MINUTE, LoanDate, ReturnDate) FROM @Loan   -- 10080（7 天）
